<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowUpRight,ClipboardList,X,Search,Check} from 'lucide-vue-next'
import {api,money,statuses} from '../api'
const route=useRoute(), router=useRouter(), admin=computed(()=>route.path.startsWith('/admin')), prefix=computed(()=>admin.value?'/admin/orders':'/orders'), role=computed(()=>admin.value?'ADMIN':'USER')
const records=ref([]),total=ref(0),page=ref(1),status=ref(''),keyword=ref(''),loading=ref(true),error=ref(''),detail=ref(null),detailLoading=ref(false),detailError=ref(''),action=ref(''),note=ref(''),acting=ref(false),actionError=ref(''),success=ref(route.query.created?'预约已提交，请在订单详情查看当前进度。租金与押金到店办理。':'')
const actionNames={confirm:'确认预约',reject:'拒绝预约',pickup:'确认领取',return:'归还验收',cancel:'取消预约'}
let version=0, detailVersion=0
async function load(reset=false){if(reset)page.value=1;const id=++version;loading.value=true;error.value='';try{const d=await api(prefix.value,{role:role.value,query:{page:page.value,pageSize:10,status:status.value,keyword:keyword.value.trim()}});if(version===id){records.value=d.records;total.value=d.total}}catch(e){if(version===id)error.value=e.message}finally{if(version===id)loading.value=false}}
async function open(id){const current=++detailVersion;detailLoading.value=true;detailError.value='';detail.value=null;action.value='';actionError.value='';try{const data=await api(`${prefix.value}/${id}`,{role:role.value});if(current===detailVersion)detail.value=data}catch(e){if(current===detailVersion)detailError.value=e.message}finally{if(current===detailVersion)detailLoading.value=false}}
function prepare(value){action.value=value;note.value='';actionError.value=''}
async function perform(){acting.value=true;actionError.value='';try{detail.value=await api(`${prefix.value}/${detail.value.id}/${action.value}`,{method:'POST',role:role.value,body:{note:note.value}});success.value=`${actionNames[action.value]}成功`;action.value='';load()}catch(e){actionError.value=e.message}finally{acting.value=false}}
function close(){if(!acting.value){detailVersion++;detail.value=null;detailError.value='';detailLoading.value=false}}
onMounted(()=>{load();if(route.query.id)open(route.query.id);if(route.query.created){const query={...route.query};delete query.created;router.replace({path:route.path,query})}})
onBeforeUnmount(()=>{version++;detailVersion++})
</script>
<template><section class="wrap admin-page"><div class="page-heading"><div><span class="eyebrow">{{admin?'RENTAL OPERATIONS':'YOUR CREATIVE JOURNEYS'}}</span><h1>{{admin?'租赁订单':'我的租赁'}}</h1><p class="muted">{{admin?'每一次交接，都有迹可循。':'从预约到归还，随时查看进度。'}}</p></div><RouterLink v-if="!admin" to="/" class="button secondary small">继续探索<ArrowUpRight :size="16"/></RouterLink></div><div v-if="success" class="alert success"><Check :size="18"/>{{success}}<button class="icon-button" aria-label="关闭提示" @click="success=''"><X :size="16"/></button></div><div class="toolbar"><select v-model="status" aria-label="订单状态" @change="load(true)"><option value="">全部状态</option><option v-for="(name,key) in statuses" :value="key" :key="key">{{name}}</option></select><form v-if="admin" class="search-box" @submit.prevent="load(true)"><Search :size="17"/><input v-model="keyword" placeholder="搜索订单号或器材"><button type="submit">搜索</button></form><button class="text-button" @click="load()" :disabled="loading">刷新</button></div><div v-if="error" class="state error">{{error}}<button class="button small" @click="load()">重试</button></div><div v-else-if="loading" class="state">正在加载订单…</div><div v-else-if="!records.length" class="state panel"><ClipboardList :size="40"/><h3>暂无{{status?'此状态的':''}}订单</h3><p>{{admin?'预约到来后会显示在这里。':'去挑选一件器材，开启下一次创作。'}}</p></div><div v-else class="order-list"><article class="order-card" v-for="o in records" :key="o.id"><div class="order-card-header"><span class="mono">{{o.orderNo}}</span><span :class="['badge',o.status.toLowerCase()]">{{statuses[o.status]||o.status}}</span></div><div class="order-card-content"><div class="order-item-icon"><ClipboardList :size="27"/></div><div class="order-main"><h3>{{o.equipmentName}}</h3><p>{{o.startDate}} <span class="muted">至</span> {{o.endDate}} <span class="muted">· {{o.rentalDays}} 天</span></p><small class="muted">实物编号 {{o.assetCode}}</small></div><div class="order-amount"><strong>¥{{money(o.rentalAmount)}}</strong><small>租金 · 押金 ¥{{money(o.depositAmount)}}</small></div><button class="button secondary small" @click="open(o.id)">查看详情<ArrowUpRight :size="16"/></button></div></article></div><div v-if="total>10" class="pagination"><button :disabled="page===1||loading" @click="page--;load()">上一页</button><span>{{page}} / {{Math.ceil(total/10)}}</span><button :disabled="page*10>=total||loading" @click="page++;load()">下一页</button></div></section>
<Teleport to="body"><div v-if="detail||detailLoading||detailError" class="modal-backdrop" @click.self="close"><section class="modal order-modal" role="dialog" aria-modal="true" aria-label="订单详情"><div class="modal-heading"><div><span class="eyebrow">RENTAL DETAILS</span><h2>订单详情</h2></div><button class="icon-button" :disabled="acting" @click="close" aria-label="关闭"><X/></button></div><p v-if="detailLoading" class="state">读取详情中…</p><p v-else-if="detailError" class="alert error">{{detailError}}</p><template v-else-if="detail"><div class="detail-status"><span :class="['badge',detail.status.toLowerCase()]">{{statuses[detail.status]}}</span><span class="mono">{{detail.orderNo}}</span></div><h2>{{detail.equipmentName}}</h2><dl class="info-grid"><div><dt>领取日期</dt><dd>{{detail.startDate}}</dd></div><div><dt>归还日期（不计费）</dt><dd>{{detail.endDate}}</dd></div><div><dt>实物编号</dt><dd>{{detail.assetCode}}</dd></div><div><dt>租期 / 日租金</dt><dd>{{detail.rentalDays}} 天 / ¥{{money(detail.dailyRate)}}</dd></div><div><dt>租金</dt><dd>¥{{money(detail.rentalAmount)}}</dd></div><div><dt>押金</dt><dd>¥{{money(detail.depositAmount)}}</dd></div></dl><p v-if="detail.remark" class="note-box">预约备注：{{detail.remark}}</p><p v-if="detail.returnNote" class="note-box">验收说明：{{detail.returnNote}}</p><p class="hint">租金及押金在线下交接。本页面状态不代表线上支付或退款。</p><div v-if="!action" class="action-row"><template v-if="admin"><button v-if="detail.status==='PENDING'" class="button" @click="prepare('confirm')">确认预约</button><button v-if="detail.status==='PENDING'" class="button danger-outline" @click="prepare('reject')">拒绝</button><button v-if="detail.status==='CONFIRMED'" class="button" @click="prepare('pickup')">办理领取</button><button v-if="detail.status==='RENTED'" class="button" @click="prepare('return')">归还验收</button></template><button v-else-if="['PENDING','CONFIRMED'].includes(detail.status)" class="button danger-outline" @click="prepare('cancel')">取消预约</button></div><form v-else class="action-form" @submit.prevent="perform"><h3>{{actionNames[action]}}</h3><p class="hint">{{action==='return'?'请记录器材外观、配件与功能验收结果。押金结算由门店线下办理。':action==='pickup'?'请确认已核验身份、检查器材并完成线下租金与押金交接。':'确认后将记录本次操作，请核对订单信息。'}}</p><label>操作说明<textarea v-model="note" maxlength="255" :required="['return','reject'].includes(action)" placeholder="填写说明" :disabled="acting"/></label><p v-if="actionError" class="alert error">{{actionError}}</p><div class="action-row"><button class="button" :disabled="acting">{{acting?'处理中…':'确认操作'}}</button><button type="button" class="button secondary" :disabled="acting" @click="action=''">返回</button></div></form><h3 class="timeline-title">流转记录</h3><ol class="timeline"><li v-for="e in detail.events||[]" :key="e.id"><span class="timeline-dot"/><div><strong>{{({CREATE:'提交预约',CONFIRM:'确认预约',REJECT:'拒绝预约',PICKUP:'领取器材',RETURN:'归还验收',CANCEL:'取消预约'})[e.action]||e.action}}</strong><small>{{e.createdAt}} · {{e.actorRole==='ADMIN'?'门店员工':'用户'}}</small><p v-if="e.note">{{e.note}}</p></div></li></ol><p v-if="!detail.events?.length" class="muted">暂无流转记录</p></template></section></div></Teleport></template>
